// ======================================================
// Prepare Run (100% Robust - Handles Webhook & Database)
// ======================================================

let inputData = $input.first()?.json || {};

// Unwrap webhook body if passed via Webhook Trigger node
if (inputData.body && typeof inputData.body === 'object') {
  inputData = inputData.body;
}

if (!inputData || Object.keys(inputData).length === 0) {
  return [{
    json: {
      hasRow: false,
      message: "No pending content found."
    }
  }];
}

// 1. If payload is already the 5-block payload (Instant Mode Webhook from FastAPI)
if (inputData.job && (inputData.job.contentId || inputData.job.id)) {
  const jobObj = { ...inputData.job, contentId: inputData.job.contentId || inputData.job.id };
  return [{ json: { ...inputData, job: jobObj } }];
}

// 2. Normalize database row (Schedule Mode GET /api/v1/content or SQLite DB)
const contentId = inputData.id || inputData.content_id || inputData.job?.contentId || inputData["Content ID"] || "CNT-" + Date.now();
const businessId = inputData.business_id || inputData.job?.businessId || inputData["Business ID"] || "";
const publishDate = inputData.publish_date || inputData["Publish Date"] || "";
const publishTime = inputData.publish_time || inputData["Publish Time"] || "";
const status = inputData.status || inputData["Status"] || "pending";
const mode = inputData.mode || "schedule";

// Platforms
const defaultPlatforms = ["LinkedIn", "Instagram", "Facebook", "X", "Threads", "WhatsApp"];
let rawPlatforms = inputData.platforms || inputData["Platform"] || defaultPlatforms;
let platforms = Array.isArray(rawPlatforms)
  ? rawPlatforms
  : String(rawPlatforms).split(",").map(p => p.trim()).filter(Boolean);

// Media normalization
const preferredMedia = String(inputData.preferred_media || inputData["Preferred Media"] || "").trim().toLowerCase();
const mediaInstructions = String(inputData.media_instructions || inputData["Media Instructions"] || "").trim();
const userImageUrl = inputData.user_image_url || inputData["User Image URL"];
const userVideoUrl = inputData.user_video_url || inputData["User Video URL"];

let media = {
  type: "none",
  url: null,
  source: null,
  generate: false,
  prompt: null,
  instructions: mediaInstructions
};

if (userImageUrl && String(userImageUrl).trim()) {
  media = { ...media, type: "image", url: String(userImageUrl).trim(), source: "user", generate: false };
} else if (userVideoUrl && String(userVideoUrl).trim()) {
  media = { ...media, type: "video", url: String(userVideoUrl).trim(), source: "user", generate: false };
} else if (preferredMedia === "image") {
  media = { ...media, type: "image", source: "generated", generate: true };
} else if (preferredMedia === "video") {
  media = { ...media, type: "video", source: "generated", generate: true };
}

// Business details
const business = inputData.business || {
  id: businessId,
  name: inputData.business_name || inputData["Business Name"] || "Elevate-X",
  type: inputData.business_type || inputData["Business Type"] || "Technology",
  about: inputData.about || inputData["About the Business"] || "",
  products: inputData.products || inputData["Products / Services"] || "",
  website: inputData.website || inputData["Website"] || "",
  logo: inputData.logo || inputData["Logo"] || "",
  targetAudience: inputData.target_audience || inputData["Target Audience"] || "",
  brandTone: inputData.brand_tone || inputData["Brand Tone"] || "",
  industry: inputData.industry || inputData["Industry"] || "",
  brandStyle: inputData.brand_style || inputData["Brand Style"] || ""
};

return [{
  json: {
    hasRow: true,
    job: {
      contentId: contentId,
      businessId: businessId,
      publishDate: publishDate,
      publishTime: publishTime,
      status: status,
      mode: mode,
      cacheBuster: Date.now()
    },
    business: business,
    content: {
      topic: String(inputData.topic || inputData["Topic"] || "").trim(),
      platforms: platforms,
      goal: inputData.goal || inputData["Content Goal"] || "",
      cta: inputData.cta || inputData["CTA"] || "",
      userPrompt: inputData.user_prompt || inputData["User Prompt"] || "",
      feedback: inputData.feedback || inputData["Feedback"] || ""
    },
    media: media
  }
}];

const data = $('Parse Agent JSON Output').first().json;

// Get the normalized media (Cloudinary)
const normalizedMedia = $('Normalize Media').first().json.media;
// If you later merge existing/generated media into one node,
// replace the above line with:
// const normalizedMedia = $('Merge Media').first().json.media;

const topic = data.topic;
const posts = Array.isArray(data.posts) ? data.posts : [];

const media = {
  ...(data.media || {}),
  ...(normalizedMedia || {})
};

const NL = "\n";

function normalizePlatform(name) {
  const n = String(name || "").toLowerCase();

  if (n.includes("linkedin")) return "LinkedIn";
  if (n.includes("insta")) return "Instagram";
  if (n.includes("face")) return "Facebook";
  if (n.includes("thread")) return "Threads";
  if (n.includes("whats")) return "WhatsApp";

  return name;
}

return posts.map(post => {

  const hashtags = Array.isArray(post.hashtags)
    ? post.hashtags
        .map(tag => tag.startsWith("#") ? tag : `#${tag}`)
        .join(" ")
    : "";

  const content = [
    post.headline,
    post.caption,
    hashtags
  ]
    .filter(Boolean)
    .join(`${NL}${NL}`);

  return {
    json: {
      topic,
      platform: normalizePlatform(post.platform),
      headline: post.headline,
      caption: post.caption,
      hashtags: post.hashtags || [],
      content,
      media
    }
  };
});

