const MAX_VIDEO_SIZE = 4 * 1024 * 1024; // 4 MB = 4,194,304 bytes

for (const item of $input.all()) {
  const fileSizeBytes = item.binary.data.bytes;

  if (fileSizeBytes > MAX_VIDEO_SIZE) {
    throw new Error(
      `LinkedIn video upload currently supports videos up to 4 MB. ` +
      `This video is ${(fileSizeBytes / (1024 * 1024)).toFixed(2)} MB.`
    );
  }

  item.json.fileSizeBytes = fileSizeBytes;
}

return $input.all();

