const logs = [];

const nodes = [
  'Prepare LinkedIn Log',
  'Prepare LinkedIn Video Log',
  'Prepare LinkedIn Text Log',

  'Prepare Facebook Image Log',
  'Prepare Facebook Video Log',
  'Prepare Facebook Text Log',

  'Prepare Instagram Image Log',
  'Prepare Instagram Video Log',

  'Prepare Threads Image Log',
  'Prepare Threads Video Log',
  'Prepare Threads Text Log',
];

for (const nodeName of nodes) {
  try {
    const items = $(nodeName).all();

    for (const item of items) {
      if (item?.json?.platform) {
        logs.push(item.json);
      }
    }
  } catch (error) {
    // Node may not have executed in this run.
    // Ignore it and continue collecting the others.
  }
}

return logs.map(log => ({
  json: log
}));

const logs = $input.all().map(item => item.json);

const now = new Date();

const date = now.toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'short',
  day: 'numeric'
});

const time = now.toLocaleTimeString('en-US', {
  hour: '2-digit',
  minute: '2-digit'
});

const publications = logs.map(log => {
  const platform = log.platform || 'Unknown';
  const status = (log.status || 'unknown').toLowerCase();
  const mediaType = (log.mediaType || 'none').toLowerCase();

  const statusText =
    status.charAt(0).toUpperCase() + status.slice(1);

  const mediaText =
    mediaType === 'none'
      ? 'Text'
      : mediaType.charAt(0).toUpperCase() + mediaType.slice(1);

  return {
    platform,
    status,
    statusText,
    mediaType,
    mediaText,
    postId: log.postId || null,
    publishedAt: log.publishedAt || null
  };
});

return [
  {
    json: {
      reportType: 'publication_report',
      date,
      time,
      publications
    }
  }
];

