const topic = $json.topic;
const media = $json.media;
const posts = $json.posts;

const discordMessages = [];

// Header
discordMessages.push(
  `**CONTENT APPROVAL**\n\n` +
  `**Topic:**\n${topic}\n\n` +
  `**Media:** ${media?.type || 'none'}\n` +
  `${media?.url || ''}`
);

// Each platform as its own message
for (const post of posts) {
  let message =
    `**${post.platform.toUpperCase()}**\n\n`;

  if (post.headline) {
    message += `**${post.headline}**\n\n`;
  }

  message += post.caption;

  if (post.hashtags?.length) {
    message += `\n\n${post.hashtags.join(' ')}`;
  }

  discordMessages.push(message);
}

return [
  {
    json: {
      topic,
      media,
      posts,
      discordMessages
    }
  }
];

