const items = $input.all();

const messages = items
  .map(item => item.json.discordMessages)
  .filter(Boolean);

return [
  {
    json: {
      discordMessage: messages.join(
        '\n\n━━━━━━━━━━━━━━━━━━━━\n\n'
      )
    }
  }
];

const outputItems = [];

for (const item of $input.all()) {
  try {
    // Get the agent response
    let data =
      item.json.output ??
      item.json.observation ??
      item.json.tool_calls;

    // If the response is an array, use the first element
    if (Array.isArray(data)) {
      data = data[0];
    }

    // Parse JSON string into an object
    if (typeof data === "string") {
      data = JSON.parse(data);
    }

    // Unwrap nested "output" objects
    while (data && data.output) {
      data = data.output;
    }

    outputItems.push({ json: data });

  } catch (error) {
    outputItems.push({
      json: {
        error: "Failed to parse agent output",
        message: error.message,
        raw: item.json,
      },
    });
  }
}

return outputItems;
